INSERT INTO `products` VALUES (1,1461750.00,62,11,'Đồ Chơi Lắp Ráp Siêu Xe Ferrari FXX K – V29 LEGO TECHNIC 42212-LG','{\"Tuổi\": \"10 tuổi trở lên\", \"Chủ đề\": \"LEGO TECHNIC ALL\", \"Giới tính\": \"Boy\", \"Thương hiệu\": \"LEGO TECHNIC\", \"Mã sản phẩm\": \"42212-LG\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Đan Mạch\"}','Đồ Chơi Lắp Ráp Siêu Xe Ferrari FXX K – V29 LEGO TECHNIC 42212-LG (897 Chi Tiết)\r\nĐộ chính xác, tốc độ và phong cách – Ferrari FXX K hội tụ tất cả!Giờ đây, bạn có thể tự tay lắp ráp phiên bản mô hình của chiếc xe hiệu suất cao này. Hoàn thiện từng chi tiết rồi thử sức chiếc xe của bạn. Mở nắp động cơ để chiêm ngưỡng động cơ V12 chân thật. Thử nghiệm bộ vi sai và quan sát piston chuyển động sinh động. Mở cửa cánh bướm và mơ về cảm giác ngồi sau tay lái chiếc siêu xe tuyệt đẹp này.\r\nBộ lắp ráp mô hình LEGO® Ferrari dành cho trẻ từ 10 tuổi trở lên\r\nLắp ráp cửa cánh bướm, nắp capo mở được và nắp động cơ mở được\r\nXây dựng động cơ V12 với piston chuyển động và thử bộ vi sai thật\r\nTận hưởng màu đỏ đặc trưng huyền thoại của Ferrari\r\nMón quà thú vị dành cho các bạn nam, nữ yêu thích bộ mô hình xe hơi\r\nLưu tiến độ, phóng to và xoay mô hình trong không gian 3D qua ứng dụng LEGO® Builder\r\nBộ LEGO® Technic™ nổi bật với các chuyển động và cơ chế thực tế\r\nBộ gồm 897 chi tiết, mô hình dài hơn 29 cm (11 inch) khi hoàn thiện',49,37,1,'2026-01-27 03:49:43'),(2,1281750.00,62,29,'Đồ Chơi Lắp Ráp Xe Thể Thao Koenigsegg Jesko Màu Trắng LEGO TECHNIC 42184 (801 Chi Tiết)','{\"Tuổi\": \"10 tuổi trở lên\", \"Chủ đề\": \"LEGO TECHNIC ALL\", \"Giới tính\": \"Boy\", \"Thương hiệu\": \"LEGO TECHNIC\", \"Mã sản phẩm\": \"42184\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"ĐAN MẠCH\"}','Đồ Chơi Lắp Ráp Xe Thể Thao Koenigsegg Jesko Màu Trắng LEGO TECHNIC  42184 (801 Chi Tiết)\r\nMang đến cảm hứng cho các bé trai và bé gái ở độ tuổi 10+ để lắp ráp chiếc siêu xe sang trọng với bộ lắp ráp LEGO® Technic™Xe thể thao Koenigsegg Jesko màu trắng (42184). Bộ lắp ráp này vinh danh một trong những chiếc siêu xe   với các tính năng thú vị dành cho những người đam mê xe hơi khám phá. Người chơi có thể mô phỏng lại các khái niệm kỹ thuật khi họ lắp ráp chi tiết động cơ V8 cảu chiếc siêu xe này. Sau đó, họ có thể kiểm tra tay lái bằng cách sử dụng phần núm có thể tháo rời bên trên khoang ngồi . Một tính năng thú vị của bộ lắp ráp này là hệ thống cửa xoắn đồng bộ lưỡng diện cho phép cửa xoay 90 độ và di chuyển ra ngoài, giống như trên chiếc siêu xe nguyên mẫu. Chiếc xe LEGO Technic này là một ý tưởng quà tặng tuyệt vời cho những trẻ yêu thích xe cộ.',22,37,1,'2026-01-27 03:49:43'),(3,977400.00,7,93,'Đồ Chơi Lắp Ráp Thùng Gạch Sáng Tạo: Xe Hơi Và Xe Tải LEGO DUPLO 10439 (80 chi tiết)','{\"Tuổi\": \"18 tháng tuổi trở lên\", \"Chủ đề\": \"LEGO DUPLO TOWN\", \"Giới tính\": \"Unisex\", \"Thương hiệu\": \"LEGO DUPLO\", \"Mã sản phẩm\": \"10439\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"ĐAN MẠCH\"}','Đồ Chơi Lắp Ráp Thùng Gạch Sáng Tạo: Xe Hơi Và Xe Tải LEGO DUPLO 10439 (80 chi tiết)\r\nĐối với trẻ mẫu giáo có sự yêu thích với các đồ chơi xe cộ, bộ lắp ráp LEGO DUPLO Thùng gạch sáng tạo: xe hơi và xe tải (10439) sẽ giúp trẻ phát triển các kỹ năng sáng tạo một cách phù hợp nhất. Với 3 đế bánh xe và 80 viên gạch, bộ lắp ráp giáo dục sáng tạo này dành cho trẻ từ 18 tháng tuổi trở lên dễ dàng chế tạo các mẫu xe ô tô đua, đi kèm cùng bục phát biểu, các mẫu xe kéo, ô tô gia đình và khung cảnh cây cối - hoặc bất kỳ phương tiện có bánh xe nào khác mà trẻ có thể nghĩ raBộ đồ chơi giáo dục này giúp cho trẻ thực hành được nhiều kỹ năng, như giải quyết vấn đề, phối hợp tay mắt và vận động tinh khi trẻ tạo ra một chiếc ô tô đồ chơi mà chúng yêu thích. Bộ LEGO cũng bao gồm một người thợ cơ khí, một cậu bé và một chú ong ngộ nghĩnh, giúp khơi dậy cách kể chuyện giàu trí tưởng tượng.\r\nBộ lắp ráp gồm 80 mảnh LEGO',41,49,1,'2026-01-27 03:49:43'),(4,503200.00,7,41,'Đồ Chơi Lắp Ráp Chậu Cây Vui Vẻ LEGO BOTANICALS 10349','{\"Tuổi\": \"9 tuổi trở lên\", \"Chủ đề\": \"LEGO BOTANICALS ICONS\", \"Giới tính\": \"Unisex\", \"Thương hiệu\": \"LEGO BOTANICALS\", \"Mã sản phẩm\": \"10349\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Đan Mạch\"}','Đồ Chơi Lắp Ráp Chậu Cây Vui Vẻ LEGO BOTANICALS 10349 (217 chi tiết)\r\nBạn muốn mang lại niềm vui và nụ cười cho mọi người?Hãy cùng tạo nên một món đồ trang trí thật xinh xắn với bộ LEGO® Botanicals – Chậu cây vui vẻ. Bé sẽ thích thú khi tự tay lắp ráp một cây phát tài trong chậu màu vàng và một cây đồng tiền (pilea) trong chậu màu xanh. Sau khi hoàn thành, bộ cây sẽ trở thành món trang trí dễ thương cho phòng ngủ hoặc góc học tập.\r\nBao gồm 2 chậu cây mini: cây phát tài trong chậu vàng và cây đồng tiền trong chậu xanh\r\nBé có thể tự lắp ráp hoặc rủ bạn bè cùng chơi để thêm phần vui nhộn\r\nTrang trí đẹp mắt cho kệ sách, bàn học hay góc LEGO yêu thích của bé\r\nLà món quà tuyệt vời cho trẻ từ 9 tuổi trở lên, cũng như dành cho người yêu cây hoặc người lớn thích LEGO\r\nCó thể kết hợp với các bộ LEGO® Botanicals khác (bán riêng) để tạo thành một khu vườn mini độc đáo\r\nGiúp bé phát huy sự sáng tạo và khả năng quan sát\r\nBộ gồm 217 mảnh ghép, cây phát tài cao khoảng 12 cm',49,49,1,'2026-01-27 03:49:43'),(5,3170300.00,7,89,'Đồ Chơi Lắp Ráp Xe Đua Nissan Skyline GT-R (R34) LEGO TECHNIC 42210','{\"Tuổi\": \"18 tuổi trở lên\", \"Chủ đề\": \"LEGO TECHNIC ALL\", \"Giới tính\": \"Boy\", \"Thương hiệu\": \"LEGO TECHNIC\", \"Mã sản phẩm\": \"42210\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Đan Mạch\"}','Đồ Chơi Lắp Ráp Xe Đua Nissan Skyline GT-R (R34) LEGO TECHNIC 42210 (1410 chi tiết)\r\nLắp ráp bộ mô hình xe hơi dành cho người lớn từ LEGO® Technic™ – chiếc Nissan Skyline GT-R (R34) trong bộ phim nổi tiếng Fast & Furious 2 Fast 2 Furious. Chi tiết tinh xảo bao gồm hệ thống lái, hệ thống treo trước và sau, động cơ 6 xi-lanh với pistons chuyển động. Thử điều chỉnh cánh gió và trải nghiệm chức năng drift đầu tiên trong LEGO Technic – nâng xe lên để tái hiện những pha drift ấn tượng như trong các cảnh đua xe yêu thích.\r\nTính năng nổi bật:\r\nBộ mô hình xe đua Fast & Furious dành cho người lớn\r\nCác chi tiết thực tế: hệ thống lái, hệ thống treo, cánh gió điều chỉnh và 3 bình NOS\r\nChức năng drift độc đáo nâng xe lên để tạo các pha drift đẹp mắt\r\nĐộng cơ 6 xi-lanh với pistons chuyển động sống động\r\nQuà tặng sáng tạo dành cho người lớn yêu thích dự án mô hình và xe hơi\r\nHướng dẫn xây dựng kỹ thuật số có trong ứng dụng LEGO® Builder\r\nBộ LEGO® Technic™ (bán riêng) dành cho người lớn với các dự án thách thức và hấp dẫn\r\nThông tin sản phẩm:\r\nGồm 1.410 mảnh ghép\r\nMô hình xe dài hơn 41 cm',22,49,1,'2026-01-27 03:49:43'),(6,2436750.00,NULL,12,'Đồ Chơi Lắp Ráp Vòng Nguyệt Quế LEGO BOTANICALS 10340 (1194 chi tiết)','{\"Tuổi\": \"18 tuổi trở lên\", \"Chủ đề\": \"LEGO BOTANICALS ICONS\", \"Giới tính\": \"Boy\", \"Thương hiệu\": \"LEGO BOTANICALS\", \"Mã sản phẩm\": \"10340\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Đan Mạch\"}','Đồ Chơi Lắp Ráp Vòng Nguyệt Quế LEGO BOTANICALS 10340 (1194 chi tiết)\r\nDành thời gian thư giãn với bộ đồ chơi trang trí nhà Lego Icons Vòng Nguyệt Quế (10340). Tái hiện vẻ đẹp của mùa thu và mùa đông với một mẫu vòng nguyệt quế đầy lôi cuốn, lý tưởng để trang trí trong mùa lễ hội. Bộ Lego độc đáo này có thể treo trên tường, đặt trên bàn hoặc trưng bày dưới dạng dây treo, mang lại vẻ đẹp tinh tế cho mọi không gian.\r\nBộ đồ chơi đi kèm với bốn vòng treo và cho phép bạn tùy chỉnh với quả mọng đỏ, xanh hoặc trắng, hoặc kết hợp các màu sắc theo sở thích. Bạn cũng có thể sắp đặt các lát cam, thanh quế, và quả thông, tạo dáng cho những tán lá xanh đậm để đạt được vẻ ngoài hoàn hảo. Hướng dẫn lắp ráp kỹ thuật số có sẵn trên ứng dụng LEGO Builder, giúp bạn dễ dàng khám phá và tận hưởng không gian thư giãn qua các dự án sáng tạo được thiết kế đặc biệt cho người lớn.\r\nĐây là món quà tuyệt vời cho mùa lễ hội hoặc bất kỳ dịp đặc biệt nào!',49,49,1,'2026-01-27 03:49:43'),(7,1095200.00,NULL,52,'Đồ Chơi Lắp Ráp Rồng Bậc Thầy Rontu LEGO NINJAGO 71842','{\"Tuổi\": \"7 tuổi trở lên\", \"Chủ đề\": \"LEGO NINJAGO PLAY THEMES\", \"Giới tính\": \"Boy\", \"Thương hiệu\": \"LEGO NINJAGO\", \"Mã sản phẩm\": \"71842\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Đan Mạch\"}','Đồ Chơi Lắp Ráp Rồng Bậc Thầy Rontu LEGO NINJAGO 71842 (381 chi tiết)\r\nGia nhập đội ninja gồm Sora, Wyldfyre, Lloyd và Rồng sư phụ Rontu trong hành trình vượt qua Zarkt – Chúa tể Xui Xẻo, kẻ đang canh giữ ngôi đền cổ. Hãy tấn công từ bầu trời với súng bắn đạn của Rontu, hoặc chiến đấu trên mặt đất bằng vũ khí đặc biệt của các ninja. Liệu các anh hùng có thể chiến thắng? Tất cả phụ thuộc vào bạn!\r\nTính năng nổi bật:\r\nBộ đồ chơi rồng cho trẻ tái hiện các pha hành động từ mùa 3 của NINJAGO® Dragons Rising\r\nRồng Rontu có thể cử động đuôi, chân, cánh, đầu và hàm – mang đến trải nghiệm sống động\r\nMô hình ngôi đền mini được lắp ghép từ gạch, ẩn chứa một bí mật bất ngờ\r\nGồm 4 minifigure: Wyldfyre, Sora, Lloyd và Zarkt – kẻ phản diện chính\r\nMón quà sinh nhật tuyệt vời cho trẻ từ 7 tuổi trở lên, yêu thích nhập vai và phiêu lưu\r\nTận hưởng trải nghiệm lắp ráp trực quan với hướng dẫn 3D trên ứng dụng LEGO® Builder\r\nCác bộ LEGO® NINJAGO® đưa trẻ đến với thế giới giả tưởng đầy phiêu lưu và hành động\r\nThông tin sản phẩm:\r\nGồm 381 mảnh ghép\r\nMô hình rồng cao hơn 13 cm',20,49,1,'2026-01-27 03:49:43'),(8,4249000.00,NULL,89,'Đồ Chơi Lắp Ráp Lâu Đài Trung Cổ Của Kỵ Sĩ LEGO CREATOR 31168','{\"Tuổi\": \"9 tuổi trở lên\", \"Chủ đề\": \"LEGO CREATOR BUILDINGS\", \"Giới tính\": \"Boy\", \"Thương hiệu\": \"LEGO CREATOR\", \"Mã sản phẩm\": \"31168\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Đan Mạch\"}','Đồ Chơi Lắp Ráp Lâu Đài Trung Cổ Của Kỵ Sĩ LEGO CREATOR 31168 (1371 Chi Tiết)\r\nQuay ngược thời gian để bước vào hành trình kịch tính tại Lâu Đài Hiệp Sĩ Cưỡi Ngựa thời Trung Cổ! Băng qua cầu kéo, khám phá phòng ngủ của đức vua, đại sảnh tráng lệ và chuồng ngựa đầy chi tiết Rồi nhảy lên lưng ngựa để bảo vệ lâu đài khỏi các thế lực thù địch đang xâm lược! Muốn thêm phần hấp dẫn? Biến tấu thành sân chơi hiệp sĩ hoặc làng trung cổ yên bình với cối xay gió!\r\nVới bộ 3in1 này, mọi khả năng sáng tạo đều nằm trong tay bạn Trẻ có thể tha hồ sáng tạo và tái tạo 3 mô hình khác nhau đậm chất trung cổ tự do hóa thân vào các câu chuyện phiêu lưu với lâu đài, trò chơi hiệp sĩ hoặc ngôi làng thời xưa Mô hình lâu đài chứa đầy chi tiết thú vị và có thể mở phía sau để chơi bên trong\r\nBộ lắp ráp đi kèm 6 nhân vật minifigure Trung Cổ siêu chất Bộ đồ chơi 3in1 là món quà tuyệt vời cho những bé sáng tạo và yêu thích thế giới thời xưa\r\nHướng dẫn lắp ráp 3D sinh động có trong ứng dụng LEGO® Builder dễ sử dụng\r\nDòng LEGO® Creator 3in1 bao gồm các chủ đề đa dạng: động vật, xe cộ và nhà cửa\r\nBộ 3in1 gồm 1.371 mảnh, lâu đài sau khi hoàn thành rộng hơn 36 cm – cực kỳ ấn tượng khi trưng bày!',18,49,1,'2026-01-27 03:49:43'),(9,2289000.00,NULL,12,'Đồ Chơi Lắp Ráp WALL-E Và EVE LEGO DISNEY PRINCESS 43279','{\"Tuổi\": \"18 tuổi trở lên\", \"Chủ đề\": \"LEGO DISNEY CLASSIC ADULT\", \"Giới tính\": \"Unisex\", \"Thương hiệu\": \"LEGO DISNEY PRINCESS\", \"Mã sản phẩm\": \"43279\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Đan Mạch\"}','Đồ Chơi Lắp Ráp WALL-E Và EVE LEGO DISNEY PRINCESS 43279 (811 chi tiết)\r\nThỏa mãn niềm đam mê lắp ráp khi bạn tạo hình WALL-E và EVE cùng các bạn đồng hành từ Disney và Pixar.Trong lúc lắp ráp, bạn có thể khám phá những gì WALL-E cất giấu trong kho lưu trữ.Giúp EVE bảo quản chồi cây an toàn để phân tích.Để M-O dọn dẹp – nhưng hãy cẩn thận kẻo cậu ấy hút nhầm Hal.Và với ứng dụng LEGO® Builder, bạn có thể cùng lắp ráp với bạn bè và gia đình.\r\nTặng người hâm mộ WALL-E của Disney và Pixar một bộ lắp ghép dành cho người lớn đầy niềm vui\r\n4 nhân vật chi tiết từ Disney và Pixar gồm WALL-E, EVE, M-O và Hal\r\nTrải nghiệm lắp ráp truyền cảm hứng với kỹ thuật nâng cao để khơi dậy sự sáng tạo\r\nBộ mô hình lấy cảm hứng từ phim, thích hợp để trưng bày tại nhà hoặc nơi làm việc\r\nÝ tưởng quà tặng tuyệt vời cho người yêu Disney, với từng chi tiết được chăm chút\r\nTải ứng dụng LEGO® Builder để trải nghiệm lắp ráp cùng nhau với bộ này\r\nHoạt động sáng tạo, thư giãn dành cho bạn hoặc một người lớn yêu thích Disney khác\r\nBộ mô hình gồm 811 mảnh ghép, với nhân vật WALL-E cao hơn 13 cm',19,49,1,'2026-01-27 03:49:43'),(10,6499000.00,NULL,96,'Đồ Chơi Lắp Ráp Siêu Xe Thể Thao Lamborghini Revuelto LEGO TECHNIC 42214','{\"Tuổi\": \"10 tuổi trở lên\", \"Chủ đề\": \"LEGO TECHNIC ALL\", \"Giới tính\": \"Boy\", \"Thương hiệu\": \"LEGO TECHNIC\", \"Mã sản phẩm\": \"42214\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Đan Mạch\"}','Đồ Chơi Lắp Ráp Siêu Xe Thể Thao Lamborghini Revuelto LEGO TECHNIC 42214 (1135 Chi Tiết)\r\nĐây chính là giấc mơ trở thành hiện thực! Lamborghini Revuelto kết hợp sức mạnh và độ chính xác để tạo nên siêu xe có một không hai.\r\nGiờ đây bạn có thể tự tay lắp ráp mô hình siêu xe Lamborghini Revuelto với bộ LEGO® Technic™ này. Khám phá hệ thống đèn cực “ngầu” với các chi tiết phát sáng trong bóng tối!\r\nCảm nhận tốc độ khi điều khiển siêu xe Revuelto bằng ứng dụng LEGO Technic CONTROL+ hiện đại!\r\nDành cho các bé từ 10 tuổi trở lên đam mê xe mô hình siêu cấp Siêu xe điều khiển từ xa sử dụng ứng dụng LEGO® Technic™ CONTROL+\r\nCó thể điều khiển tiến lùi linh hoạt và chiêm ngưỡng hiệu ứng phát sáng cực chất\r\nBao gồm pin sạc cho mô hình xe (không kèm cáp sạc)\r\nMón quà lý tưởng cho các bé yêu thích mô hình ô tô và xe điều khiển\r\nHướng dẫn lắp ráp 3D sinh động có sẵn trong ứng dụng LEGO® Builder dễ sử dụng\r\nDòng LEGO® Technic™ tái hiện chân thực các chuyển động và cơ chế như xe thật\r\nBộ mô hình gồm 1.135 mảnh, khi hoàn thiện dài hơn 40 cm – đậm chất siêu xe đẳng cấp',22,49,1,'2026-01-27 03:49:43'),(11,869000.00,7,18,'Đồ Chơi Lắp Ráp Siêu Xe Thể Thao Bugatti Centodieci LEGO SPEED CHAMPIONS 77240','{\"Tuổi\": \"9 tuổi trở lên\", \"Chủ đề\": \"LEGO SPEED CHAMPIONS ALL\", \"Giới tính\": \"Boy\", \"Thương hiệu\": \"LEGO SPEED CHAMPIONS\", \"Mã sản phẩm\": \"77240\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Đan Mạch\"}','Đồ Chơi Lắp Ráp Siêu Xe Thể Thao Bugatti Centodieci LEGO SPEED CHAMPIONS 77240 (291 Chi Tiết)\r\nChinh phục đỉnh cao của thiết kế và tốc độ với Bugatti Centodieci – siêu phẩm hypercar đẳng cấp thế giới, nay được tái hiện sống động trong phiên bản LEGO® Speed Champions.\r\nLấy cảm hứng từ dòng EB 110 huyền thoại, mẫu mô hình này mang theo từng đường nét thiết kế mang tính biểu tượng của Bugatti – từ khe hút gió khí động học đến bộ mâm xe độc đáo.\r\nCùng với minifigure tài xế Bugatti, bạn có thể thỏa sức tái hiện những pha bứt phá ngoạn mục trên đường đua hoặc trưng bày như một tác phẩm nghệ thuật.\r\nMô hình LEGO® Speed Champions Bugatti Centodieci – siêu xe hypercar tối thượng\r\nBao gồm nhân vật minifigure tài xế Bugatti, sẵn sàng vào buồng lái cho các màn nhập vai gay cấn\r\nTái hiện chính xác thiết kế thật với các khe hút gió và mâm xe đặc trưng của Bugatti\r\nSau khi chơi, có thể trưng bày đẹp mắt trên bàn làm việc, kệ sách hoặc tủ trưng bày\r\nQuà tặng lý tưởng dành cho trẻ từ 9 tuổi trở lên và người đam mê mô hình xe cao cấp Kết hợp cùng các mẫu xe khác thuộc dòng LEGO® Speed Champions (bán riêng) để mở rộng bộ sưu tập.  Các set LEGO® Speed Champions giúp trẻ em và người lớn lắp ráp những mẫu xe siêu thực\r\nBao gồm 291 chi tiết, xe có chiều dài khoảng 15 cm (6 inch) sau khi hoàn thiện',17,49,1,'2026-01-27 03:49:43'),(12,9539000.00,NULL,19,'Đồ Chơi Lắp Ráp Tàu Vũ Trụ Lớp Firespray Của Jango Fett LEGO STAR WARS 75409','{\"Tuổi\": \"18 tuổi trở lên\", \"Chủ đề\": \"LEGO STAR WARS TM\", \"Giới tính\": \"Boy\", \"Thương hiệu\": \"LEGO STAR WARS\", \"Mã sản phẩm\": \"75409\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Đan Mạch\"}','Đồ Chơi Lắp Ráp Tàu Vũ Trụ Lớp Firespray Của Jango Fett LEGO STAR WARS 75409 (2970 Chi Tiết)\r\nTái hiện những khoảnh khắc kinh điển từ Star Wars: Attack of the Clones™ khi bạn lắp ráp phiên bản Ultimate Collector Series hoành tráng của tàu Firespray-Class – thuộc sở hữu của Jango Fett!\r\nTàu được thiết kế cực kỳ chi tiết với buồng lái có thể tháo rời dành cho Jango Fett và Boba Fett nhí, cùng một khoang chứa bom xung kích seismic.\r\nCó thể trưng bày ở chế độ hạ cánh hoặc đặt trên giá đỡ dựng đứng để chiêm ngưỡng từ mọi góc độ.\r\nLEGO® Star Wars™ UCS – Mô hình trưng bày tàu chiến đỉnh cao dành cho nhà sưu tầm\r\nGồm 2 minifigure độc quyền: Jango Fett và Boba Fett thời thơ ấu\r\nThiết kế chi tiết với: buồng lái mở được, khoang chứa bom xung kích, cùng nhiều điểm nhấn kỹ thuật\r\nCó thể trưng bày trên mặt phẳng hoặc dựng đứng trên giá đỡ chuyên dụng để tạo hiệu ứng đang bay\r\nMón quà hoàn hảo cho người hâm mộ Star Wars trưởng thành và nhà sưu tầm UCS chính hiệu\r\nTải ứng dụng LEGO® Builder để xem hướng dẫn lắp ráp 3D tương tác trực quan\r\nDòng mô hình LEGO® Star Wars™ dành cho người lớn mang đến trải nghiệm sáng tạo, thư giãn và chất lượng cao\r\nTàu chiến có chiều dài hơn 44 cm – được lắp ráp từ hàng ngàn mảnh ghép đầy tinh xảo',21,49,1,'2026-01-27 03:49:43'),(13,4869000.00,NULL,96,'Đồ Chơi Lắp Ráp Cỗ Máy Hủy Diệt Juggernaut LEGO STAR WARS 75413','{\"Tuổi\": \"9 tuổi trở lên\", \"Chủ đề\": \"LEGO STAR WARS TM\", \"Giới tính\": \"Boy\", \"Thương hiệu\": \"LEGO STAR WARS\", \"Mã sản phẩm\": \"75413\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Đan Mạch\"}','Đồ Chơi Lắp Ráp Cỗ Máy Hủy Diệt Juggernaut LEGO STAR WARS 75413 (813 Chi Tiết)\r\nLăn bánh ra chiến trường cùng chiếc Republic Juggernaut hùng mạnh, từng xuất hiện trong Star Wars: The Clone Wars™!Hãy cùng Ki-Adi-Mundi và Chỉ huy Bacara điều khiển cỗ xe 10 bánh siêu ngầu này. Đặt các binh sĩ Thủy Quân Lục Chiến Thiên Hà vào buồng lái trước và sau. Nghiêng thân xe để điều khiển hướng đi. Từ tháp quan sát, hãy truy tìm các Droid Chiến Đấu và kích hoạt súng bắn đạn ở tháp pháo phía sau để khai hỏa!\r\nĐồ chơi mô hình LEGO® Star Wars™ – Xe vận chuyển dành cho trẻ emGồm 5 minifigure LEGO® Star Wars™ và 3 Droid Chiến Đấu, kèm phụ kiện đầy đủ\r\nTính năng lái xe bằng cách nghiêng thân xe, 2 buồng lái, tháp quan sát nâng lên, và súng bắn đạn\r\nMở phần hông và tháo phần trên để khám phá khoang trung tâm chi tiết bên trong\r\nMón quà LEGO® Star Wars™ chất lượng cao, lý tưởng cho trẻ từ 9 tuổi trở lên\r\nTăng thêm phần thú vị với ứng dụng LEGO® Builder hỗ trợ lắp ráp\r\nKhám phá thêm các bộ sưu tập LEGO® Star Wars™ (bán riêng) phù hợp với mọi lứa tuổi\r\nKích thước mô hình sau khi hoàn thành: dài hơn 31 cm',21,49,1,'2026-01-27 03:49:43'),(14,9119000.00,NULL,29,'Đồ Chơi Lắp Ráp Lâu Đài Neuschwanstein LEGOARCHITECTURE 21063','{\"Tuổi\": \"18 tuổi trở lên\", \"Chủ đề\": \"LEGO ARCHITECTURE ALL\", \"Giới tính\": \"Boy\", \"Thương hiệu\": \"LEGOARCHITECTURE\", \"Mã sản phẩm\": \"21063\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Đan Mạch\"}','Đồ Chơi Lắp Ráp Lâu Đài Neuschwanstein LEGOARCHITECTURE 21063 (3455 Chi Tiết)\r\nĐắm mình trong vẻ đẹp huyền thoại của lâu đài NeuschwansteinHãy lắp ráp khung cảnh rừng núi bao quanh tòa lâu đài và thay đổi màu lá cây để chuyển mùa từ hạ sang thu. Dựng lên những tòa tháp cao vút, sân trong với các bậc cầu thang liên kết, và khám phá những chi tiết nội thất tinh xảo ẩn bên trong khi bạn dần hoàn thiện toàn bộ lâu đài. Cuối cùng, chiêm ngưỡng công trình biểu tượng qua toàn bộ vẻ đẹp kỳ ảo của nó.\r\nBộ mô hình lâu đài Neuschwanstein dành cho người lớn yêu thích lịch sử và du lịchTái hiện chân thực lâu đài với các tòa tháp, sân trong, cảnh quan xung quanh và nhiều chi tiết khác\r\nLá cây có thể thay đổi, cho phép bạn chuyển cảnh từ mùa hè sang mùa thu tùy theo sở thích\r\nTrong quá trình xây dựng, bạn sẽ khám phá nội thất thu nhỏ được thiết kế tinh tế bên trong lâu đài\r\nMón quà tuyệt vời dành cho người yêu thích lịch sử, đam mê du lịch, người sưu tầm LEGO® hoặc chính bạn\r\nTrải nghiệm lắp ráp hiện đại và thú vị hơn với ứng dụng LEGO® Builder\r\nLà một phần của bộ sưu tập LEGO® dành riêng cho người lớn (bán riêng), dành cho những ai yêu thích các hoạt động sáng tạo\r\nMô hình sưu tầm gồm 3.455 mảnh ghép, có chiều rộng hơn 46 cm',49,49,1,'2026-01-27 03:49:43'),(15,916300.00,NULL,6,'Xe tập đi 3 trong 1 PEEK A BOO EU461542','{\"Tuổi\": \"6 tháng tuổi trở lên\", \"Chủ đề\": \"PEEK TODDLERS TOY\", \"Giới tính\": \"Preschool\", \"Thương hiệu\": \"PEEK A BOO\", \"Mã sản phẩm\": \"EU461542\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Việt Nam\"}','Đồ Chơi PEEK A BOO Xe Tập Đi 3 Trong 1 EU461542\r\n\r\nCho bé từ 6 tháng là một trong những sản phẩm được ưa chuộng nhất trong dòng đồ chơi giáo dục và vận động\r\n\r\nPEEK A BOO là thương hiệu đồ chơi - đồ dùng trẻ em với mong muốn mang lại tất cả những sản phẩm cần thiết nhất trên từng chặng đường phát triển của bé với chất lượng tốt, an toàn, giá cả phải chăng.\r\n\r\nXe tập đi là một trong những món không thể thiếu cho bé từ 6 tháng – 3 tuổi. Xe tập đi 3 trong 1 Peek A Boo không chỉ là một chiếc xe thông thường mà còn tích hợp nhiều công dụng giúp kéo dài thời gian sử dụng sản phẩm, vừa tiện lợi cho bé, vừa tiết kiệm cho mẹ.\r\n\r\n',27,9,1,'2026-01-27 03:49:43'),(16,335200.00,NULL,57,'Bộ lục lạc 6 món cho bé PEEK A BOO 939A','{\"Tuổi\": \"0 tuổi trở lên\", \"Chủ đề\": \"PEEK NEWBORN TOYS\", \"Giới tính\": \"Preschool\", \"Thương hiệu\": \"PEEK A BOO\", \"Mã sản phẩm\": \"939A\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Việt Nam\"}','\r\nBỘ LỤC LẠC 6 MÓN CHO BÉ PEEK A BOO  939A\r\n\r\nTrẻ từ 3 tháng tuổi sẽ bắt đầu học cách sử dụng các ngón tay để cầm, nắm đồ vật đồng thời có những phản xạ với âm thanh, màu sắc và hình dáng khác nhau!Bộ lục lạc 6 món của Peek A-Boo chính là sự lựa chọn tuyệt vời nhất cho bé. Bộ lục lạc gồm:\r\n1. Quả bóng thông minh:\r\n2. Kèn Trumpet\r\n\r\n6. Điện thoại di động:\r\n\r\n\r\n',27,8,1,'2026-01-27 03:49:43'),(17,629250.00,NULL,21,'Bộ trống kèm piano vui nhộn PEEK A BOO PAB003','{\"Tuổi\": \"3 tuổi trở lên\", \"Chủ đề\": \"PEEK TODDLERS TOY\", \"Giới tính\": \"Preschool\", \"Thương hiệu\": \"PEEK A BOO\", \"Mã sản phẩm\": \"PAB003\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Việt Nam\"}','Bộ  Đồ Chơi Trống Kèm Piano Vui Nhộn   Peek A Boo PAB003\r\nBộ nhạc cụ 5 trong 1 - Peek A Boo\r\nMột sản phẩm kết hợp nhiều nhạc cụ cho bé thoải mái trải nghiệm và sáng tạo hết mình:\r\n- Piano\r\n- Xylophone\r\n-   Cymbal\r\n-   Trống\r\n-   Micro\r\nĐặc biệt, đàn Pinao có thể chỉnh 4 chế độ âm thanh khác nhau:\r\n-   Chế độ âm thanh Piano\r\n-   Chế độ Solmization\r\n-     Chế độ âm thanh kèn Trumpet\r\n-     Chế độ âm thanh đàn Ghita\r\nVới bộ trống, bé cũng có thể thoải mái sáng tạo với 3 chế độ:\r\n-     Âm thanh nhạc Jazz\r\n-     Âm thanh nhạc Djembe\r\n-   Hoặc chọn phát các bài nhạc có sẵn\r\nVới Xylophone, bé cũng có thể chọn 4 chế độ sau:\r\n-     Chế độ tone Glockenspiel\r\n-     Chế độ tiếng động vật: 7 âm thanh động vật thường gặp\r\n-   Chế độ đếm số\r\n-   Chế độ tone Xylophone\r\nKích thước sản phẩm: 17 x 13 x 11 inch\r\nPin: 3 x 1.5V AA (không bao gồm trong sản phẩm)\r\nVài nét về thương hiệu:\r\nPEEK A BOO là thương hiệu đồ chơi - đồ dùng trẻ em với mong muốn mang lại tất cả những sản phẩm cần thiết nhất trên từng chặng đường phát triển của bé với chất lượng tốt, an toàn, giá cả phải chăng.',32,8,1,'2026-01-27 03:49:43'),(18,249000.00,NULL,38,'Đồ chơi bảng vẽ nam châm cho bé - Cá voi cam đáng yêu PEEK A BOO PAB029','{\"Tuổi\": \"3 tuổi trở lên\", \"Chủ đề\": \"PEEK TODDLERS TOY\", \"Giới tính\": \"Unisex\", \"Thương hiệu\": \"PEEK A BOO\", \"Mã sản phẩm\": \"PAB029\", \"Nơi sản xuất\": \"TRUNG QUỐC\", \"Xuất xứ thương hiệu\": \"VIỆT NAM\"}','Đồ Chơi PEEK A BOO Bảng Vẽ Nam Châm Cho Bé - Cá Voi Cam Đáng Yêu PAB029\r\n** Ở lứa tuổi lên 3 bé sẽ bắt đầu khám phá mọi thứ xung quanh,và phát triển sự sáng tạo của mình qua việc vẽ ,hoặc viết những gì bé thích. Điều đó có thể khiến ba mẹ đau đầu khi bé thường vẽ khắp nhà hoặc những nơi ba mẹ khó vệ sinh.Vì vậy một chiếc Bảng Vẽ Nam Châm là giải pháp giúp bé tự do phát triển sáng tạo,ba mẹ cũng yên tâm hơn.\r\n- Phù hợp cho bé từ 3+\r\n- Giúp bé phát triển được tư duy Logic, sự sáng tạo và khéo léo\r\n- Bảng vẽ bao gồm: bảng nam châm, bút vẽ, 3 con dấu hình dáng dễ thương\r\n- Chất liệu làm từ nhựa an toàn, có thể tái chế được\r\n- Bảng vẽ có 4 màu cho bé tự do sáng tạo và nhận biết màu sắc\r\n- Xóa dễ dàng với 1 cái gạt cần ngang qua, giữ cho tay bé luôn được sạch sẽ.\r\n- Đặc biệt bút nam châm được liên kết với dây tránh bị rơi hoặc mất.\r\n- PEEK A BOO là thương hiệu đồ chơi - đồ dùng trẻ em Độc quyền của Mykingdom và hoàn toàn xuất xứ tại Việt Nam với mong muốn mang lại tất cả những sản phẩm cần thiết nhất trên từng chặng đường phát triển của bé với chất lượng tốt, an toàn, giá cả phải chăng.',32,13,1,'2026-01-27 03:49:43'),(19,499000.00,36,94,'Học chữ, số và hình học cùng điều khiển Scout LEAPFROG 80-606200','{\"Tuổi\": \"6 tháng tuổi trở lên\", \"Chủ đề\": \"LEAPFROG EDUCATIONAL TOY\", \"Giới tính\": \"Preschool\", \"Thương hiệu\": \"LEAPFROG\", \"Mã sản phẩm\": \"80-606200\", \"Nơi sản xuất\": \"TRUNG QUỐC\", \"Xuất xứ thương hiệu\": \"Mỹ\"}','\r\n\r\nĐồ Chơi LEAPFROG Học Chữ, Số Và Hình Học Cùng Điều Khiển Scout 80-606200\r\n\r\n\r\nĐồ chơi Leapfrog học chữ, số và hình học cùng điều khiển Scout 80-606200là một thiết bị gồm các nút bấm về chữ, số, hình học cho các bé thỏa sức khám phá và học hỏi được những kiến thức bổ ích.\r\n\r\nĐồ chơi giáo dụcđến từ Leapfrogcó các đặc điểm nổi bật sau:\r\n\r\nĐồ chơi Leapfrog học chữ, số và hình học cùng điều khiển Scout 80-606200gồm có:\r\n\r\nVài nét về thương hiệu đồ chơi:\r\n\r\nLeapfrog là thương hiệu đồ chơi hàng đầu của Mỹ trong lĩnh vực giáo dục giải trí, được thành lập vào năm 1995. Các sản phẩm của LeapFrog có tích hợp chương trình dạy ngoại ngữ cho bé với nhiều hiệu ứng ánh sáng và âm thanh hấp dẫn với giọng tiếng Anh chuẩn Mỹ, giúp rèn luyện kĩ năng tư duy, sáng tạo và vận động tinh cho các bé. Đồ chơi Leapfrog luôn bắt kịp xu hướng, trở thành thương hiệu đang rất được ưa chuộng và cũng là sự lựa chọn hàng đầu của nhiều gia đình.',32,9,1,'2026-01-27 03:49:43'),(20,699000.00,36,93,'Đồ Chơi Bộ 10 Siêu Xe Hot Wheels 54886','{\"Tuổi\": \"3 tuổi trở lên\", \"Chủ đề\": \"HOT WHEELS DIECAST BASIC\", \"Giới tính\": \"Boy\", \"Thương hiệu\": \"HOT WHEELS\", \"Mã sản phẩm\": \"54886\", \"Nơi sản xuất\": \"Malaysia\", \"Xuất xứ thương hiệu\": \"Mỹ\"}','\r\nĐồ Chơi Bộ 10 Siêu Xe Hot Wheels 54886 - Giao hàng ngẫu nhiên\r\nĐồ chơi bộ 10 siêu xe Hot Wheels 54886là món đồ chơi yêu thích của các nhà sưu tập, những người đam mê xe hơi và người hâm mộ đua xe ở mọi lứa tuổi. Những chiếc xe Hot Wheels cực chất, được thiết kế vô cùng tinh xảo với tỷ lệ thu nhỏ 1/64 từ chiếc xe ngoài đời thật. Tuyệt vời hơn, bộ 10 siêu xe còn tích hợp thêm một siêu xe đặc biệt, chỉ được bán kèm trong bộ này.\r\nBộ 10 chiếc xe sưu tập die-castHot Wheels 54886có các đặc điểm nổi bật sau:\r\nĐồ chơibộ 10 siêu xe Hot Wheels 54886bao gồm:\r\nVài nét về thương hiệu đồ chơi:\r\nHot Wheels là dòng đồ chơi xe mô hình cực kì được yêu thích tại Mỹ và nhiều nước trên thế giới, trực thuộc tập đoàn đồ chơi Mattel nổi tiếng hàng đầu hiện nay. Với kỹ thuật hiện đại và thiết kế tinh xảo, những chiếc xe Hot Wheels không chỉ là đồ chơi, mà nó còn mang đến trải nghiệm hoàn hảo cho người mê xe mô hình. Mô hình xe Hot Wheels giúp trẻ phát triển tư duy, kích thích trí sáng tạo và rèn luyện sự linh hoạt cho đôi tay của các bé.',31,5,1,'2026-01-27 03:49:43'),(21,2159400.00,36,23,'Đồ chơi mô hình tỷ lệ 1:16 xe tải cần cẩu SCANIA BRUDER BRU03570','{\"Tuổi\": \"4 tuổi trở lên\", \"Chủ đề\": \"BRUDER CONSTRUCTION\", \"Giới tính\": \"Preschool\", \"Thương hiệu\": \"BRUDER\", \"Mã sản phẩm\": \"BRU03570\", \"Nơi sản xuất\": \"ĐỨC\", \"Xuất xứ thương hiệu\": \"ĐỨC\"}','Mô Hình Xe Theo Tỷ Lệ Thu Nhỏ 1:16 Xe Tải Cần Cẩu- BRUDER BRU03570\r\nMô hình xe theo tỷ lệ thu nhỏ 1:16 xe tải cần cẩu – BRUDER BRU03570là một trong những sản phẩm hàng đầu của thương hiệu đồ chơi Bruder. Xe tải cần cẩu lấy cảm hứng từ thực tế cuộc sống, giúp bé hiểu biết hơn về nghề kỹ sư xây dựng. Sản phẩm được thiết kế với hệ thống đèn và chuông báo hiệu giống với xe ngoài đời thật, kích thích sự tò mò, khả năng khám phá của trẻ. Các đường nét của món đồ chơi được thiết kế tỉ mỉ, tinh tế, mang đến trải nghiệm chân thật nhất cho bé yêu của bạn.\r\nĐồ chơi dạng mô hình theo tỷ lệ thu nhỏ 1:16 xe tải cần cẩutrở thành sự lựa chọn của nhiều bậc phụ huynh trên thế giới bởi những đặc điểm nổi bật sau:\r\n- Cần trục xe cao đến 1,3m khi cánh tay cẩu vươn ra hết cỡ\r\n- Thiết kế vững chắc, không góc cạnh, hạn chế làm trầy xước da bé.\r\n- Sản phẩm được làm từ nhựa ABS cao cấp, tránh biến dạng khi va đập, kéo dài thời gian sử dụng.\r\n- Xe được mô phỏng y như thật cùng màu vàng chủ đạo đẹp mắt giúp bé hiểu biết thêm về hoạt động của xe ngoài thực tế. Tăng vốn hiểu biết của trẻ.\r\n- Sản phẩm phù hợp với các bé trai trên 3 tuổi.\r\nĐồ chơi Mô hình xe theo tỷ lệ thu nhỏ 1:16 xe tải cần cẩu – BRUDER BRU03570gồm:\r\n01 Xe tải cần cẩu BRU03570.\r\nGiá trị sản phẩm mang lại:\r\n\r\n\r\n-Xe mô hìnhgiúp bé phát triển các kỹ năng vận động của trẻ thông qua việc khám phá và sử dụng các chức năng của xe\r\n- Khuyến khích trẻ tìm hiểu về các ngành nghề liên quan đến các mẫu xe có thật trong đời sống\r\n- Bố mẹ có thể kết hợp các mẫu xe cứu hỏa, xe rác, xe cảnh sát,… để lồng ghép các bài học về kĩ năng sống, ước mơ, các kiến thức cơ bản trong cuộc sống,…\r\nVài nét về thương hiệu đồ chơi:\r\nThương hiệuBruder được thành lập vào 1926 - là thương hiệu đồ chơi mô hình kích thước lớn 1:16 được thiết kế và sản xuất tại Đức. Tất cả các dòng xe Bruder đều được mua bản quyền của hãng xe ngoài đời thật.. Toàn bộ các sản phẩm của Bruder đều đạt tiêu chuẩn chất lượng cao của Mỹ (ASTM) và Châu Âu (EN71), chứng nhận sản phẩm an toàn Spiel Gut (ra đời từ 1954) dựa trên các yếu tố để đánh giá đó là: giá trị mang lại khi chơi, tay nghề sản xuất, độ bền, thiết kế, kích thước, chất lượng sản phẩm, sự phù hợp ở các độ tuổi cụ thể, v.v.Thông qua việc chơi tưởng tượng và hình ảnh sáng tạo, đồ chơi Bruder giúp trẻ học hỏi các giá trị bền vững, trang bị cho trẻ một tương lai tươi sáng.\r\n',23,5,1,'2026-01-27 03:49:43'),(22,299000.00,36,54,'Đồ Chơi Xe Đua F1 1:43 Red Bull Racing RB20 (2024) MAISTO 18-38097','{\"Tuổi\": \"15 tuổi trở lên\", \"Chủ đề\": \"MAISTO 1:43 FORMULA RACING\", \"Giới tính\": \"Unisex\", \"Thương hiệu\": \"MAISTO\", \"Mã sản phẩm\": \"01/18-38097\", \"Nơi sản xuất\": \"Trung Quốc\", \"Xuất xứ thương hiệu\": \"Hồng Kong\"}','Đồ Chơi Xe Đua F1 1:43 Red Bull Racing RB20 (2024) MAISTO 01/18-38097\r\nĐồ chơi mô hình tỉ lệ 1:43 xe đua F1 gây ấn tượng với thiết kế cực ngầu.\r\nMô phỏng thiết kế thực tế. Dùng để trưng bày và sưu tập. Toàn bộ khung xe được làm đúc bằng kim loại, nội thất xe , lốp xe được làm từ cao su tự nhiên, các chi tiết ống xả và lưới tản nhiệt được xi bóng . Sơn tĩnh điện cho nước sơn sáng bóng, mỏng, bền.Red Bull Racing RB20 (2024) là mẫu xe F1 tiên tiến, trang bị khí động học tối ưu, động cơ Honda RA624H mạnh mẽ, cải tiến từ RB19, giúp Red Bull duy trì vị thế dẫn đầu mùa giải 2024.\r\nVài nét về thương hiệu Maisto:Maisto International Inc là thương hiệu đồ chơi của Cheong May Group Hồng Kông, chuyên sản xuất các mô hình đúc của xe ô tô, máy bay và xe máy, nổi tiếng từ những năm 1990. Đồ chơi Maisto được bày bán trong các cửa hàng và siêu thị đồ chơi trên toàn thế giới, nhận được sự yêu thích của hầu hết các bé thiếu nhi và nhận được hứng thú của rất nhiều người lớn đam mê mô hình xe.',37,5,1,'2026-01-27 03:49:43'),(23,719100.00,36,3,'Mô Hình Xe Tải Chở Du Thuyền SIKU 1849','{\"Tuổi\": \"3 tuổi trở lên\", \"Chủ đề\": \"SIKU SUPER1:87\", \"Giới tính\": \"Boy\", \"Thương hiệu\": \"SIKU\", \"Mã sản phẩm\": \"1849\", \"Nơi sản xuất\": \"TRUNG QUỐC\", \"Xuất xứ thương hiệu\": \"Đức\"}','Xe tải chở du thuyền - 1849Kích thước hộp hàng: 30.5 x 15.1 x 7.1 cmMẫu siêu du thuyền Drettmann với thiết kế nội thất sang trọng và tinh tế mang đẩy cảm hứng sáng tạo.Xe vận chuyển siêu tải MAN với hệ thống trục bánh cùng lớp cao su cao cấp có thể vận chuyển du thuyền an toàn và vững chắc trên mọi chuyến hành trình du lịch sắp tới.Chưa dừng lại ở đó, bộ sản phẩm còn kèm 2 nhân vật để tăng tính trải nghiệm khi chơi của bé. Du thuyền hoàn toàn có thể mở phần nắp phía trên để bé có thể quan sát nội thất bên trong, chắc chắn là điểm đặc biệt mà nhiều mô hình hiện tại không làm được. Hứa hẹn giúp bé có những giây phút vui chơi đầy hào hứng nhưng vẫn đảm bảo an toàn cho bé từ chất lượng đồ chơi Đức.\r\n\r\nĐẶC ĐIỂM NỔI BẬT CỦA XE MÔ HÌNH KIM LOẠI SIKU:• CHẤT LƯỢNG ĐỨC – Được sản xuất bởi các chất liệu kim loại cao cấp, đạt tiêu chuẩn Châu Âu về an toàn đồ chơi.• ĐỒ CHƠI GIÁO DỤC – Thiết kế mô phỏng dựa trên các mẫu xe thực tế, không chỉ có xe hơi mà còn bao gồm cả các loại xe khác trong thành phố giúp bé vừa chơi vừa học.• BẢN QUYỀN- Các dòng xe đều có bản quyền từ thương hiệu xe nổi tiếng trên thế giới• CHI TIẾT TINH XẢO – dàn đèn, vỏ xe, một số dòng xe có thể mở cửa• ĐA DẠNG MẪU MÃ – hơn 200 mẫu xe khác nhauNhững chiếc xe mô hình luôn khơi gợi trí tò mò và là nguồn cảm hứng cho các bé trai thỏa sức chơi, khơi sáng tạo.Chính vì thế dòng đồ chơi xe mô hình luôn giữ vững vị trí hàng đầu trong Top đồ chơi được bé trai yêu thích. Không chỉ là một thú vui sưu tập, xe mô hình SIKU còn giúp bé học về thế giới xung quanh và phát triển trí tuệ, thế giới quan của mình.\"',31,5,1,'2026-01-27 03:49:43'),(24,1429000.00,36,71,'Đường đua xoắn kép siêu tốc xếp gọn Hot Wheels HOT WHEELS GFH85','{\"Tuổi\": \"5 tuổi trở lên\", \"Chủ đề\": \"HOT WHEELS ACTION\", \"Giới tính\": \"Boy\", \"Thương hiệu\": \"HOT WHEELS\", \"Mã sản phẩm\": \"GFH85\", \"Nơi sản xuất\": \"TRUNG QUỐC\", \"Xuất xứ thương hiệu\": \"Mỹ\"}','\r\nMô  Hình  Đồ  Chơi  Hot  Wheels  Đường  Đua  Xoắn  Kép  Siêu  Tốc  Xếp  Gọn  GFH85\r\n✅  Nhận  h